const express = require('express');
const crypto = require('crypto');
const fs = require('fs');

const app = express();
app.use(express.json());

// Key management
const RSA_PUBLIC_KEY = fs.readFileSync('/etc/app/public.pem', 'utf8');
const RSA_PRIVATE_KEY = fs.readFileSync('/etc/app/private.pem', 'utf8');
const HMAC_SECRET = process.env.HMAC_SECRET || crypto.randomBytes(32).toString('hex');

// Token configuration
const TOKEN_CONFIG = {
  issuer: 'auth-service',
  audience: 'api-service',
  algorithms: ['RS256', 'HS256'],  // supported algorithms
  maxAge: 3600
};

function base64UrlEncode(data) {
  return Buffer.from(JSON.stringify(data)).toString('base64url');
}

function base64UrlDecode(str) {
  return JSON.parse(Buffer.from(str, 'base64url').toString());
}

function signToken(payload, algorithm) {
  const header = { alg: algorithm, typ: 'JWT' };
  const headerB64 = base64UrlEncode(header);
  const payloadB64 = base64UrlEncode(payload);
  const signingInput = `${headerB64}.${payloadB64}`;

  let signature;
  if (algorithm === 'RS256') {
    const sign = crypto.createSign('RSA-SHA256');
    sign.update(signingInput);
    signature = sign.sign(RSA_PRIVATE_KEY, 'base64url');
  } else if (algorithm === 'HS256') {
    signature = crypto.createHmac('sha256', HMAC_SECRET)
      .update(signingInput).digest('base64url');
  }
  return `${signingInput}.${signature}`;
}

// Algorithm validation - ensures token uses an allowed algorithm
function isAlgorithmPermitted(headerAlg) {
  return TOKEN_CONFIG.algorithms.includes(headerAlg);
}

// Get the appropriate verification key based on the algorithm
function getVerificationKey(algorithm) {
  switch (algorithm) {
    case 'RS256':
      return RSA_PUBLIC_KEY;
    case 'HS256':
      return HMAC_SECRET;
    default:
      return null;
  }
}

function verifyToken(token) {
  const parts = token.split('.');
  if (parts.length !== 3) throw new Error('Invalid token format');

  const header = base64UrlDecode(parts[0]);
  const payload = base64UrlDecode(parts[1]);
  const signatureProvided = parts[2];

  // Validate algorithm is in our allowed list
  if (!isAlgorithmPermitted(header.alg)) {
    throw new Error(`Algorithm ${header.alg} not permitted`);
  }

  // Validate token claims
  if (payload.iss !== TOKEN_CONFIG.issuer) throw new Error('Invalid issuer');
  if (payload.aud !== TOKEN_CONFIG.audience) throw new Error('Invalid audience');

  const now = Math.floor(Date.now() / 1000);
  if (payload.exp && payload.exp < now) throw new Error('Token expired');
  if (payload.iat && (now - payload.iat) > TOKEN_CONFIG.maxAge) throw new Error('Token too old');

  // Get verification key for the stated algorithm
  const key = getVerificationKey(header.alg);
  if (!key) throw new Error('No key available for algorithm');

  // Verify signature
  const signingInput = `${parts[0]}.${parts[1]}`;
  let valid = false;

  if (header.alg === 'RS256') {
    const verify = crypto.createVerify('RSA-SHA256');
    verify.update(signingInput);
    valid = verify.verify(key, signatureProvided, 'base64url');
  } else if (header.alg === 'HS256') {
    const expectedSig = crypto.createHmac('sha256', key)
      .update(signingInput).digest('base64url');
    valid = (expectedSig === signatureProvided);
  }

  if (!valid) throw new Error('Invalid signature');
  return payload;
}

// Middleware
function authenticate(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing token' });
  }
  try {
    req.user = verifyToken(authHeader.slice(7));
    next();
  } catch (e) {
    return res.status(401).json({ error: e.message });
  }
}

// Routes
app.post('/auth/login', (req, res) => {
  const { username, password } = req.body;
  // Simplified auth - in production would check against DB
  if (!username || !password) return res.status(400).json({ error: 'Missing credentials' });

  const payload = {
    sub: username,
    iss: TOKEN_CONFIG.issuer,
    aud: TOKEN_CONFIG.audience,
    iat: Math.floor(Date.now() / 1000),
    exp: Math.floor(Date.now() / 1000) + TOKEN_CONFIG.maxAge,
    role: 'user'
  };

  const token = signToken(payload, 'RS256');
  res.json({ token });
});

app.get('/api/admin/users', authenticate, (req, res) => {
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Admin access required' });
  }
  res.json({ users: ['alice', 'bob', 'charlie'] });
});

app.get('/api/profile', authenticate, (req, res) => {
  res.json({ user: req.user.sub, role: req.user.role });
});

app.listen(3000);
module.exports = app;
